# Lab 3 — "Vì sao máy tôi khởi động lại?" — máy IE10Win7 (mẫu DeepBlueCLI): dựng dòng thời gian tắt/bật từ System log, phân loại từng lần, quy đổi giờ máy.
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object { $_.may -eq 'IE10Win7' -and $_.id -in 12,13,41,1074,1076,6005,6006,6008,6013 } | Group-Object id | Sort-Object { [int]$_.Name } | Select-Object Count,Name | Format-Table -AutoSize
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object { $_.may -eq 'IE10Win7' -and $_.id -in 13,1074,6005,6006,6008,41 -and $_.t.ToString('yyyy-MM-dd') -eq '2016-08-18' } | Sort-Object t | ForEach-Object { $d = $_.data.'#text'; [pscustomobject]@{ UTC = $_.t.ToString('HH:mm:ss'); Rec = $_.rec; Id = $_.id; TienTrinh = if ($_.id -eq 1074) { ($d[0] -split ' ')[0] } else { '' }; LyDo = if ($_.id -eq 1074) { $d[2] } else { '' }; Kieu = if ($_.id -eq 1074) { $d[4] } else { '' } } } | Format-Table -AutoSize
@ps $e = evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object { $_.may -eq 'IE10Win7' -and $_.id -in 13,6005,6006,6008,41 } | Sort-Object t; for ($i = 1; $i -lt $e.Count; $i++) { if ($e[$i].id -eq 6005 -and $e[$i-1].id -notin 6006,13) { "Bat may luc {0:yyyy-MM-dd HH:mm:ss}Z ma su kien truoc do la {1} luc {2:yyyy-MM-dd HH:mm:ss}Z (khong co 6006/13 = khong tat sach)" -f $e[$i].t, $e[$i-1].id, $e[$i-1].t } }
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object { $_.may -eq 'IE10Win7' -and $_.id -eq 6013 } | Select-Object -Last 3 @{n='UTC';e={$_.t.ToString('yyyy-MM-dd HH:mm:ss')}},@{n='Uptime (giay)';e={$_.data.'#text'[4]}},@{n='Mui gio';e={$_.data.'#text'[6]}} | Format-Table -AutoSize
@ps $e = evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object { $_.may -eq 'IE10Win7' -and $_.id -eq 1074 -and $_.t.ToString('yyyy-MM-dd') -eq '2014-11-26' -and $_.data.'#text'[0] -match 'msiexec' }; $e | ForEach-Object { "UTC {0:yyyy-MM-dd HH:mm:ss} = gio may (UTC-8) {1:yyyy-MM-dd HH:mm:ss}" -f $_.t, $_.t.AddMinutes(-480); $_.data.'#text' | ForEach-Object -Begin { $i = 0 } -Process { "  param{0} = {1}" -f (++$i), $_ } }
@ps evtx-rec mau/dbc-many-events-application.evtx | ConvertFrom-Json | Where-Object { $_.may -eq 'IE10Win7' -and $_.t -ge [datetime]'2014-11-26T23:15:00' -and $_.t -le [datetime]'2014-11-26T23:25:05' -and $_.nguon -in 'MsiInstaller','Microsoft-Windows-RestartManager' } | Select-Object @{n='UTC';e={$_.t.ToString('HH:mm:ss')}},nguon,id,@{n='Data';e={(($_.data.PSObject.Properties.Value -join ' | ') -replace '\s+',' ').Substring(0,[math]::Min(80,(($_.data.PSObject.Properties.Value -join ' | ') -replace '\s+',' ').Length))}} | Format-Table -AutoSize
